$valueAdjustments = is_array($depreciationData['value_adjustments'] ?? null) ? $depreciationData['value_adjustments'] : [];
$depreciationEscape = static fn (string $value): string => htmlspecialchars($value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
$depreciationMoney = static fn (int|string $minor): string => number_format(((int) $minor) / 100, 2, '.', ',');
$depreciationStatus = static fn (string $status): string => match ($status) {
    'SUBMITTED', 'POSTED', 'ACTIVE' => 'text-emerald-600',
    'CANCELLED', 'REVERSED', 'SUPERSEDED' => 'text-destructive',
    default => 'text-amber-600',
};
