nter gap-2" data-confirm-submit data-confirm-message="Confirm catch-up posting through this date. Only pending due lines will post."><input type="hidden" name="csrf" value="<?= $depreciationEscape(bx_csrf_token()) ?>"><input type="hidden" name="module_view" value="assets-maintenance"><input type="hidden" name="section" value="asset-depreciation-schedule"><input type="hidden" name="action" value="catchup_asset_depreciation_schedule"><input type="hidden" name="schedule_key" value="<?= $depreciationEscape((string) $schedule['schedule_key']) ?>"><input class="h-8 rounded-md border bg-background px-2 text-xs" type="date" name="through_date" required value="<?= date('Y-m-d') ?>"><button type="submit" data-confirm-submit-action class="h-8 rounded-md border px-2.5 text-xs font-medium">Catch up</button></form><form method="post" class="inline-flex items-center gap-2" data-confirm-submit data-confirm-message="Confirm cancellation. Every posted line will receive an additive Finance reversal."><input type="hidden" name="csrf" value="<?= $depreciationEscape(bx_csrf_token()) ?>"><input type="hidden" name="module_view" value="assets-maintenance"><input type="hidden" name="section" value="asset-depreciation-schedule"><input type="hidden" name="action" value="cancel_asset_depreciation_schedule"><input type="hidden" name="schedule_key" value="<?= $depreciationEscape((string) $schedule['schedule_key']) ?>"><input class="h-8 w-36 rounded-md border bg-background px-2 text-xs" name="cancellation_reason" required maxlength="500" placeholder="Reversal reason"><button type="submit" data-confirm-submit-action class="h-8 rounded-md border px-2.5 text-xs font-medium">Reverse</button></form><?php else: ?><span class="text-xs text-muted-foreground">Immutable</span><?php endif; ?></div></article><?php endforeach; ?></div>
        <?php endif; ?>
